sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {
    response.setContentType('application/json');
    try {
        if (!gs.hasRole('x_2316161_bjit_e_0.employee'))
            throw { status: 403, code: 'forbidden', message: 'You do not have permission to view leave approvals.' };
        var result = new x_2316161_bjit_e_0.BjitLeaveApproval().myQueue();
        response.setStatus(200);
        response.setBody(result);
    } catch (e) {
        if (e && e.status && e.code) {
            response.setStatus(e.status);
            response.setBody({ code: e.code, message: e.message });
        } else {
            gs.error('BJIT leave my-queue failed: ' + e);
            response.setStatus(500);
            response.setBody({ code: 'queue_failed', message: 'Unable to load leave approvals. Please try again.' });
        }
    }
})(request, response);
